import * as React from 'react';
import * as SpotlightCardPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface SpotlightCardProps extends React.ComponentPropsWithoutRef<typeof SpotlightCardPrimitive.SpotlightCard> {
  className?: string;
}

export const SpotlightCard = React.forwardRef<HTMLDivElement, SpotlightCardProps>(
  ({ className, children, ...props }, ref) => (
    <SpotlightCardPrimitive.SpotlightCard
      ref={ref}
      className={clsx(
        'relative overflow-hidden rounded-2xl border border-border bg-card p-6 shadow-sm transition-shadow hover:shadow-md will-change-transform',
        className
      )}
      {...props}
    >
      {children}
    </SpotlightCardPrimitive.SpotlightCard>
  )
);
SpotlightCard.displayName = 'SpotlightCard';

