solid.code:
import { Component, JSX, splitProps } from 'solid-js';

export interface SpotlightCardProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const SpotlightCard: Component<SpotlightCardProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <div
      class={`relative overflow-hidden rounded-2xl border border-border bg-card p-6 shadow-sm transition-shadow hover:shadow-md will-change-transform ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </div>
  );
};

